let resolve;
const p = new Promise((r) => {
  resolve = r;
});
resolve(p);
p.then(
  () => console.log(1),
  (e) => console.log(e.name === 'TypeError' ? 2 : 0),
);

Promise.resolve({
  then(resolve, reject) {
    resolve(1);
    reject(2);
  },
}).then(
  (n) => console.log(n),
  (n) => console.log(n),
);

Promise.resolve({
  then() {
    throw 6;
  },
}).catch((n) => console.log(n));

Promise.resolve(1)
  .finally(() => Promise.resolve(9))
  .then((n) => console.log(n));

const { promise, resolve } = Promise.withResolvers();
console.log(typeof resolve === 'function' ? 1 : 0);
resolve(4);
promise.then((n) => console.log(n));

async function f() {
  const n = await {
    then(resolve) {
      resolve(3);
    },
  };
  console.log(n);
}
f();
console.log(8);

Promise.all([
  {
    then(resolve) {
      resolve(1);
    },
  },
  2,
]).then(([a, b]) => {
  console.log(a);
  console.log(b);
});

const order = [];
function job(id) {
  order.push(id);
  return Promise.resolve(id);
}
async function seq() {
  await job(1);
  await job(2);
}
async function par() {
  const a = job(3);
  const b = job(4);
  await a;
  await b;
}
par();
seq();
console.log(order.join(''));

const p = Promise.reject(1);
p.catch((n) => console.log(n));
p.catch((n) => console.log(n + 1));

async function f() {
  return Promise.resolve(5);
}
f().then((v) => console.log(typeof v === 'number' ? 1 : 0));

const a = new Promise((_, reject) => {
  queueMicrotask(() => reject(1));
});
const b = Promise.reject(2);
Promise.all([a, b]).catch((n) => console.log(n));

let n = 0;
Promise.all([]).then(() => {
  n = 1;
});
console.log(n);

Promise.any([
  Promise.reject(4),
  Promise.reject(5),
]).catch((e) => {
  console.log(e.errors[0]);
  console.log(e.errors[1]);
});

async function f() {
  return {
    then(resolve) {
      resolve(Promise.resolve(7));
    },
  };
}
f().then((v) => console.log(typeof v === 'number' ? v : 0));
